argv:
$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-activate-15pm-j1.mjs'
try {
[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},6500);
try{
const x=await(await fetch('http://127.0.0.1:17447/json/version')).json();
const ws=new WebSocket(x.webSocketDebuggerUrl);
ws.addEventListener('open',()=>ws.send(JSON.stringify({id:1,method:'Target.activateTarget',params:{targetId:'EF27777D4E798E704D04D5D474887AFA'}})),{once:true});
ws.addEventListener('message',e=>{let z=JSON.parse(e.data);if(z.id===1){console.log(JSON.stringify({activated:!!z.result,error:z.error?.message||null,target_id:'EF27777D4E798E704D04D5D474887AFA'}));process.exit(0)}});
ws.addEventListener('error',()=>{console.log(JSON.stringify({error:'ws_error'}));process.exit(0)},{once:true});
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,130)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
} finally { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
